contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(v > 0, "v must be positive");
        require(address(c).balance >= v, "c must have enough ether");
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;
        c.withdraw(v); if (__ESBMC_reverted()) return;
        assert(address(c).balance == cBalBefore - v && address(this).balance == selfBalBefore + v);
    }

    receive() external payable {}
}

