// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(v > 0);
        vm.assume(address(c).balance >= v);
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;
        try c.withdraw(v) {} catch { return; }
        assertTrue(address(c).balance == cBalBefore - v && address(this).balance == selfBalBefore + v);
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
